import React, { useEffect, useState } from 'react';
import axios from 'axios';

function AdminBlockedUsers() {
  const [blockedUsers, setBlockedUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');

  const fetchBlockedUsers = async () => {
    try {
      const response = await axios.get('http://localhost:8080/users/blocked', {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setBlockedUsers(response.data);
    } catch (err) {
      console.error('Eroare la obținerea utilizatorilor blocați:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleUnblock = async (userId) => {
    try {
      await axios.put(`http://localhost:8080/users/unblock/${userId}`, {}, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setMessage(`Utilizatorul cu ID ${userId} a fost deblocat.`);
      fetchBlockedUsers();  
    } catch (err) {
      console.error('Eroare la deblocare:', err);
    }
  };

  useEffect(() => {
    fetchBlockedUsers();
  }, []);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Utilizatori blocați</h2>
      {loading ? (
        <p>Se încarcă...</p>
      ) : blockedUsers.length === 0 ? (
        <p>Nu există utilizatori blocați.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Username</th>
              <th>Email</th>
              <th>Acțiune</th>
            </tr>
          </thead>
          <tbody>
            {blockedUsers.map((user) => (
              <tr key={user.id}>
                <td>{user.id}</td>
                <td>{user.username}</td>
                <td>{user.email}</td>
                <td>
                  <button onClick={() => handleUnblock(user.id)}>
                    Deblochează
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {message && <p style={{ color: 'green' }}>{message}</p>}
    </div>
  );
}

export default AdminBlockedUsers;
